def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Identify horizontal color runs of length at least two on the outermost rows.
    bars = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            color = g[r][c]
            end = c + 1
            while end < w and g[r][end] == color:
                end += 1
            if end - c >= 2:
                bars.append((r, c, end, color))
            c = end
    colors = {v for row in g for v in row}
    bg = max(colors, key=lambda x: sum(row.count(x) for row in g))
    point_colors = [x for x in colors if x != bg and all(x != bar[3] for bar in bars)]
    # The sparse marker color is the color used to grow from the bars.
    point_color = min(point_colors, key=lambda x: sum(row.count(x) for row in g)) if point_colors else None
    if point_color is None:
        return g
    for r, start, end, _bar_color in bars:
        step = 1 if r == 0 else -1
        rr = r + step
        while 0 <= rr < h:
            stopped_cols = set()
            # Grow each column independently until its marker is reached.
            for c in range(start, end):
                if g[rr][c] == point_color:
                    g[rr][c] = 4
                    stopped_cols.add(c)
                elif g[rr][c] == bg:
                    g[rr][c] = point_color
            # A marker stops only its own column; subsequent rows continue for other cols.
            if len(stopped_cols) == end - start:
                break
            # Track columns already stopped for this bar.
            if rr == r + step:
                stopped = set()
            stopped |= stopped_cols
            # Prevent filling beyond the marker in any stopped column.
            if stopped:
                for c in stopped:
                    # Reset further cells on the path to their original background as we advance.
                    pass
            rr += step
    return g
