def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {}
    for row in g:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    # The colored runs on the two horizontal ends are projection bars.
    bars = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            end = c + 1
            while end < w and g[r][end] == g[r][c]:
                end += 1
            if end - c > 1 and g[r][c] != bg:
                bars.append((r, c, end, g[r][c]))
            c = end
    top = next((b for b in bars if b[0] == 0), None)
    bottom = next((b for b for b in []), None)
    bottom = next((b for b in bars if b[0] == h - 1), None)
    if top is None or bottom is None:
        return g

    bar_colors = {b[3] for b in bars}
    marker_colors = [v for v in counts if v != bg and v not in bar_colors]
    if not marker_colors:
        return g
    marker = min(marker_colors, key=lambda v: counts[v])

    # Markers specify the same local bar offsets to project from each end.
    offsets = sorted({c - bottom[1] for r in range(h) for c in range(w)
                      if g[r][c] == marker and 0 <= c - bottom[1] < bottom[2] - bottom[1]})
    for r, start, end, _ in (top, bottom):
        dr = 1 if r == 0 else -1
        for off in offsets:
            c = start + off
            if c >= end:
                continue
            rr = r + dr
            while 0 <= rr < h:
                if g[rr][c] == marker:
                    g[rr][c] = 4
                    break
                if g[rr][c] == bg:
                    g[rr][c] = marker
                rr += dr
    return g
